}

run_phase2_oa_mse_candidate() {
  local i="$1" cid gpu protocol rx new_tx unknown_tx k_old k_new seed unknown_threshold openmax_quantile openmax_min_threshold adapter_rank adapter_steps adapter_lr kappa out_dir query_per_tx max_samples
  cid="${CAND_ID[$i]}"; gpu="${CAND_GPU[$i]}"; protocol="${ROW_PROTOCOL[$i]}"; rx="${ROW_TARGET_RX[$i]}"; new_tx="${ROW_NEW_TX[$i]}"; unknown_tx="${ROW_UNKNOWN_TX[$i]}"; k_old="${ROW_K_OLD[$i]}"; k_new="${ROW_K_NEW[$i]}"; seed="${ROW_SEED[$i]}"; unknown_threshold="${ROW_UNKNOWN_THRESHOLD[$i]}"; openmax_quantile="${ROW_OPENMAX_QUANTILE[$i]}"; openmax_min_threshold="${ROW_OPENMAX_MIN_THRESHOLD[$i]}"; adapter_rank="${ROW_ADAPTER_RANK[$i]}"; adapter_steps="${ROW_ADAPTER_STEPS[$i]}"; adapter_lr="${ROW_ADAPTER_LR[$i]}"; kappa="${ROW_KAPPA[$i]}"; source_anchor_weight="${ROW_SOURCE_ANCHOR_WEIGHT[$i]}"; source_ce_weight="${ROW_SOURCE_CE_WEIGHT[$i]}"; unknown_moat_weight="${ROW_UNKNOWN_MOAT_WEIGHT[$i]}"; unknown_moat_margin="${ROW_UNKNOWN_MOAT_MARGIN[$i]}"; pseudo_unknown_samples="${ROW_PSEUDO_UNKNOWN_SAMPLES_PER_PAIR[$i]}"; pseudo_unknown_offset="${ROW_PSEUDO_UNKNOWN_OFFSET_SCALE[$i]}"; pseudo_unknown_target_shift_samples="${ROW_PSEUDO_UNKNOWN_TARGET_SHIFT_SAMPLES_PER_CLASS[$i]}"; pseudo_unknown_target_shift_offset="${ROW_PSEUDO_UNKNOWN_TARGET_SHIFT_OFFSET_SCALE[$i]}"; old_neighborhood_weight="${ROW_OLD_NEIGHBORHOOD_WEIGHT[$i]}"; old_neighborhood_samples="${ROW_OLD_NEIGHBORHOOD_SAMPLES_PER_CLASS[$i]}"; old_neighborhood_radius="${ROW_OLD_NEIGHBORHOOD_RADIUS[$i]}"; old_retention_quantile="${ROW_OLD_RETENTION_QUANTILE[$i]}"; old_surrogate_margin_weight="${ROW_OLD_SURROGATE_MARGIN_WEIGHT[$i]}"; old_surrogate_margin="${ROW_OLD_SURROGATE_MARGIN[$i]}"; old_surrogate_evidence_margin="${ROW_OLD_SURROGATE_EVIDENCE_MARGIN[$i]}"; old_anchor_override_min_quality="${ROW_OLD_ANCHOR_OVERRIDE_MIN_QUALITY[$i]}"
  out_dir="${RUNS_ROOT}/${cid}"
  query_per_tx=50
  max_samples=200
  mkdir -p "${out_dir}"
  echo "[S2-OA-MSE-BEGIN] cid=${cid} protocol=${protocol} rx=${rx} new=${new_tx} unknown=${unknown_tx} k_old=${k_old} k_new=${k_new} seed=${seed} threshold=${unknown_threshold} openmax_q=${openmax_quantile} openmax_min=${openmax_min_threshold} adapter_rank=${adapter_rank} adapter_steps=${adapter_steps} adapter_lr=${adapter_lr} kappa=${kappa} old_neighbor=${old_neighborhood_weight} old_ret_q=${old_retention_quantile} old_surr_w=${old_surrogate_margin_weight} old_surr=${old_surrogate_margin} old_surr_ev=${old_surrogate_evidence_margin} old_anchor_q=${old_anchor_override_min_quality} target_shift=${pseudo_unknown_target_shift_samples}@${pseudo_unknown_target_shift_offset}"
  env PYTHONPATH="${ROOT}/code:${ROOT}:${PYTHONPATH:-}" CUDA_VISIBLE_DEVICES="${gpu}" "${PYTHON}" -u "${ROOT}/code/export_spaceborne_features.py"     --ckpt "${TEACHER_CKPT}" --wisig_pkl "${WISIG_PKL}" --new_wisig_pkl "${NEW_WISIG_PKL}"     --out_npz "${out_dir}/features.npz" --feature_name z_id     --source_tx_ids "${SOURCE_TX_IDS}" --source_rxs "${CEN51_TRAIN_RXS}"     --target_old_tx_ids "${TARGET_OLD_TX_IDS}" --target_old_rxs "${rx}" --target_old_channel_view satellite     --target_old_sat_scenarios clear_leo,low_elev_leo,rain_leo,storm_mp,mixed_orbit --target_old_sat_seed "$((seed + 111))"     --new_tx_ids "${new_tx}" --new_rxs "${rx}" --unknown_tx_ids "${unknown_tx}"     --target_new_channel_view satellite --target_new_sat_scenarios clear_leo,low_elev_leo,rain_leo,storm_mp,mixed_orbit --target_new_sat_seed "$((seed + 222))"     --wisig_equalized 1 --wisig_domain rx_day --wisig_out_len 256 --max_samples_per_combo 0 --max_samples_per_tx "${max_samples}" --batch_size 512 --device cuda:0 --seed "${seed}"
  local eval_cmd=(env PYTHONPATH="${ROOT}/code:${ROOT}:${PYTHONPATH:-}" CUDA_VISIBLE_DEVICES="${gpu}" "${PYTHON}" -u "${ROOT}/code/eval_spaceborne_fewshot.py"     --protocol "${protocol}" --feature_npz "${out_dir}/features.npz" --output_json "${out_dir}/metrics.json" --manifest_json "${out_dir}/manifest.json" --score_table_csv "${out_dir}/score_table.csv"     --source_tx_ids "${SOURCE_TX_IDS}" --target_old_tx_ids "${TARGET_OLD_TX_IDS}" --new_tx_ids "${new_tx}" --unknown_tx_ids "${unknown_tx}"     --target_old_support_per_tx "${k_old}" --target_old_query_per_tx "${query_per_tx}" --shots "${k_new}" --source_proto_per_tx 20 --source_query_per_tx 20 --query_per_tx "${query_per_tx}"     --unknown_threshold "${unknown_threshold}" --gate_mode oa_mse --openmax_tail_size 20 --openmax_quantile "${openmax_quantile}" --openmax_min_threshold "${openmax_min_threshold}"     --oa_mse_adapter_rank "${adapter_rank}" --oa_mse_adapter_steps "${adapter_steps}" --oa_mse_adapter_lr "${adapter_lr}" --kappa "${kappa}" --oa_mse_source_anchor_weight "${source_anchor_weight}" --oa_mse_source_ce_weight "${source_ce_weight}" --oa_mse_unknown_moat_weight "${unknown_moat_weight}" --oa_mse_unknown_moat_margin "${unknown_moat_margin}" --pseudo_unknown_samples_per_pair "${pseudo_unknown_samples}" --pseudo_unknown_offset_scale "${pseudo_unknown_offset}" --pseudo_unknown_target_shift_samples_per_class "${pseudo_unknown_target_shift_samples}" --pseudo_unknown_target_shift_offset_scale "${pseudo_unknown_target_shift_offset}" --oa_mse_old_neighborhood_weight "${old_neighborhood_weight}" --old_neighborhood_samples_per_class "${old_neighborhood_samples}" --old_neighborhood_radius "${old_neighborhood_radius}" --oa_mse_old_surrogate_margin_weight "${old_surrogate_margin_weight}" --old_surrogate_margin "${old_surrogate_margin}" --old_surrogate_evidence_margin "${old_surrogate_evidence_margin}" --old_anchor_override_min_quality "${old_anchor_override_min_quality}" --old_retention_quantile "${old_retention_quantile}" --old_acc_target 0.9 --seen_new_acc_target 0.75 --seed "${seed}")
  "${eval_cmd[@]}"
  echo "[S2-OA-MSE-END] cid=${cid}"
}

launch_candidate() {
  local i="$1" cid gpu kind lane log_path pid
  cid="${CAND_ID[$i]}"; gpu="${CAND_GPU[$i]}"; kind="${CAND_KIND[$i]}"; lane="${CAND_LANE[$i]:-}"
  if [[ -z "${lane}" ]]; then
    if [[ "${kind}" == "safe_ssdg" || "${kind}" == "safe_ssdg_cvs_r01" || "${kind}" == "meta_ssl" ]]; then lane="phase1"; else lane="phase2"; fi
  fi
  log_path="${LOG_ROOT}/${cid}.out"
  if [[ "${lane}" == "phase1" && "${kind}" != "safe_ssdg" && "${kind}" != "safe_ssdg_cvs_r01" ]]; then
    CAND_STATUS[$i]="failed_unsupported_phase1_kind"
    event_row "${cid}" "FAILED_LOCAL_SCHEMA" "gpu=${gpu}" "lane=phase1" "reason=unsupported_phase1_kind:${kind}"
    return 70
  fi
  if [[ "${lane}" == "phase1" && "${PHASE1_LANE_ACTIVE}" != "0" ]]; then
    CAND_STATUS[$i]="deferred_phase1_active"
    event_row "${cid}" "DEFERRED_RETRY_CAPACITY" "gpu=${gpu}" "lane=phase1" "reason=phase1_lane_active"
    return 0
  fi
  if [[ "${lane}" == "phase2" && "${PHASE2_LANE_ACTIVE}" != "0" ]]; then
    CAND_STATUS[$i]="deferred_phase2_active"
    event_row "${cid}" "DEFERRED_RETRY_CAPACITY" "gpu=${gpu}" "lane=phase2" "reason=phase2_lane_active"
    return 0
  fi
  if [[ "${lane}" == "phase2" && "${PHASE2_LOCAL_PATCH_REQUIRED}" == "1" ]]; then
    CAND_STATUS[$i]="deferred_phase2_local_verify"
    event_row "${cid}" "DEFERRED_RETRY_LOCAL_VERIFY" "gpu=${gpu}" "lane=phase2" "reason=phase2_local_patch_required"
    return 0
  fi
  if [[ "${DRY_RUN}" == "1" ]]; then
    if [[ "${lane}" == "phase1" ]]; then
      echo "[S1-DRY-RUN] cid=${cid} slot=${CAND_SLOT[$i]} gpu=${gpu} kind=${kind} lane=${lane} entrypoint=run_phase1_safe_ssdg_candidate module=SSDG.train_ssdg split=tx_rx_day_1_7_2 ratios=0.1L/0.7U/0.2Val seed=${ROW_SEED[$i]} log=${log_path}"
    else
      echo "[S2-DRY-RUN] cid=${cid} slot=${CAND_SLOT[$i]} gpu=${gpu} kind=${kind} lane=${lane} protocol=${ROW_PROTOCOL[$i]} rx=${ROW_TARGET_RX[$i]} new=${ROW_NEW_TX[$i]} unknown=${ROW_UNKNOWN_TX[$i]} threshold=${ROW_UNKNOWN_THRESHOLD[$i]} openmax_q=${ROW_OPENMAX_QUANTILE[$i]} openmax_min=${ROW_OPENMAX_MIN_THRESHOLD[$i]} adapter_rank=${ROW_ADAPTER_RANK[$i]} adapter_steps=${ROW_ADAPTER_STEPS[$i]} kappa=${ROW_KAPPA[$i]} source_ce=${ROW_SOURCE_CE_WEIGHT[$i]} unknown_moat=${ROW_UNKNOWN_MOAT_WEIGHT[$i]} unknown_margin=${ROW_UNKNOWN_MOAT_MARGIN[$i]} old_neighbor=${ROW_OLD_NEIGHBORHOOD_WEIGHT[$i]} old_ret_q=${ROW_OLD_RETENTION_QUANTILE[$i]} old_surr_w=${ROW_OLD_SURROGATE_MARGIN_WEIGHT[$i]} old_surr_ev=${ROW_OLD_SURROGATE_EVIDENCE_MARGIN[$i]} old_anchor_q=${ROW_OLD_ANCHOR_OVERRIDE_MIN_QUALITY[$i]} target_shift=${ROW_PSEUDO_UNKNOWN_TARGET_SHIFT_SAMPLES_PER_CLASS[$i]}@${ROW_PSEUDO_UNKNOWN_TARGET_SHIFT_OFFSET_SCALE[$i]} log=${log_path}"
    fi
    CAND_STATUS[$i]="dry_run"
    return 0
  fi
  if [[ "${kind}" == "safe_ssdg" || "${kind}" == "safe_ssdg_cvs_r01" ]]; then
    (run_phase1_safe_ssdg_candidate "${i}" > "${log_path}" 2>&1) &
  else
    (run_phase2_oa_mse_candidate "${i}" > "${log_path}" 2>&1) &
  fi
  pid="$!"
  CAND_PID[$i]="${pid}"
  CAND_STATUS[$i]="running"
  event_row "${cid}" "LAUNCHED" "gpu=${gpu}" "lane=${lane}" "pid=${pid};log=${log_path}"
}

log_msg "[S2-SCHEDULER] run_id=${RUN_ID} dry_run=${DRY_RUN} candidates=${#CAND_ID[@]} phase1=safe_ssdg_executable phase2=resolved_manytx_oa_mse_target_shift_pseudo_unknown_boundary_v1"
for i in "${!CAND_ID[@]}"; do
  log_msg "[S2-CANDIDATE] idx=${i} id=${CAND_ID[$i]} slot=${CAND_SLOT[$i]} gpu=${CAND_GPU[$i]} kind=${CAND_KIND[$i]} lane=${CAND_LANE[$i]} rx=${ROW_TARGET_RX[$i]} new=${ROW_NEW_TX[$i]} unknown=${ROW_UNKNOWN_TX[$i]}"
done

source "${ROOT}/tools/stage2_queue_runner_template.sh"
stage2_run_queue_scheduler
